steps.script:
var b = L.bounds, x0 = Math.round(b[0].as('px')), y0 = Math.round(b[1].as('px')), x1 = Math.round(b[2].as('px')), y1 = Math.round(b[3].as('px'));
var W = Math.round(d.width.as('px')), H = Math.round(d.height.as('px')), lm = x0, tm = y0, rm = W - x1, bm = H - y1;
function strip(sx0, sy0, sx1, sy1, px, py, anchor) {
  d.activeLayer = L; d.selection.select([[sx0, sy0], [sx1, sy0], [sx1, sy1], [sx0, sy1]], SelectionType.REPLACE, 0, false);
  executeAction(S2T('copyToLayer'), undefined, DialogModes.NO);
  var p = d.activeLayer; p.resize(px, py, anchor); p.merge(); L = d.activeLayer; }
strip(x0, y0, x0 + 1, y1, 100 * (lm + 1), 100, AnchorPosition.MIDDLERIGHT);
strip(x1 - 1, y0, x1, y1, 100 * (rm + 1), 100, AnchorPosition.MIDDLELEFT);
strip(x0, y0, x1, y0 + 1, 100, 100 * (tm + 1), AnchorPosition.BOTTOMCENTER);
strip(x0, y1 - 1, x1, y1, 100, 100 * (bm + 1), AnchorPosition.TOPCENTER);
strip(x0, y0, x0 + 1, y0 + 1, 100 * (lm + 1), 100 * (tm + 1), AnchorPosition.BOTTOMRIGHT);
strip(x1 - 1, y0, x1, y0 + 1, 100 * (rm + 1), 100 * (tm + 1), AnchorPosition.BOTTOMLEFT);
strip(x0, y1 - 1, x0 + 1, y1, 100 * (lm + 1), 100 * (bm + 1), AnchorPosition.TOPRIGHT);
strip(x1 - 1, y1 - 1, x1, y1, 100 * (rm + 1), 100 * (bm + 1), AnchorPosition.TOPLEFT);
d.selection.deselect();
say('bleed ' + lm + ' / ' + tm + ' / ' + rm + ' / ' + bm + ' px (left / top / right / bottom), art ' + (x1 - x0) + ' x ' + (y1 - y0) + ' px');

var S = Math.round(4 * 300 / 25.4), LEN = Math.round(3.5 * 300 / 25.4), tw = 1920, th = 1080;
var BL = Math.floor((Math.round(d.width.as('px')) - tw) / 2), BT = Math.floor((Math.round(d.height.as('px')) - th) / 2), B = Math.max(BL, BT);
d.resizeCanvas(UnitValue(Math.round(d.width.as('px')) + 2 * S, 'px'), UnitValue(Math.round(d.height.as('px')) + 2 * S, 'px'), AnchorPosition.MIDDLECENTER);
var pg = d.artLayers.add(); pg.name = 'paper'; d.selection.selectAll(); d.selection.fill(hexc('#FFFFFF')); d.selection.deselect(); pg.move(L, ElementPlacement.PLACEAFTER);
var mk = d.artLayers.add(); mk.name = 'crop marks'; d.activeLayer = mk;
var X0 = S + BL, Y0 = S + BT;
function box(a, b, c, e) { d.selection.select([[a, b], [c, b], [c, e], [a, e]], SelectionType.REPLACE, 0, false); d.selection.fill(hexc('#000000')); }
var xs = [X0, X0 + tw], ys = [Y0, Y0 + th], i;
for (i = 0; i < 2; i++) {
  box(xs[i] - 1, Y0 - B - LEN, xs[i] + 1, Y0 - B); box(xs[i] - 1, Y0 + th + B, xs[i] + 1, Y0 + th + B + LEN);
  box(X0 - B - LEN, ys[i] - 1, X0 - B, ys[i] + 1); box(X0 + tw + B, ys[i] - 1, X0 + tw + B + LEN, ys[i] + 1); }
d.selection.deselect();
say('canvas ' + d.width.as('px') + ' x ' + d.height.as('px') + ' px; trim box ' + tw + ' x ' + th + ' px at (' + X0 + ', ' + Y0 + '); slug ' + S + ' px; marks ' + LEN + ' px long, 2 px wide, ' + B + ' px off the trim');

var f = new File(OUT + '/ps_bleed_marks.pdf'); var o = new PDFSaveOptions(); o.layers = false; o.preserveEditing = false;
d.saveAs(f, o, true);
if (!f.exists || f.length < 1000) throw new Error('ps_bleed_marks.pdf was not written');
f.encoding = 'BINARY'; f.open('r'); var s = f.read(); f.close(); var m = s.match(/\/MediaBox\s*\[([^\]]+)\]/);
say('ps_bleed_marks.pdf ' + f.length + ' bytes' + (m ? '; MediaBox ' + m[1].replace(/\s+/g, ' ') + ' pt' : '; MediaBox not readable'));

var out = new Folder(OUT); if (!out.exists) out.create();
var f = new File(out.fsName + '/ps_press.pdf');
var o = new PDFSaveOptions(); o.PDFStandard = PDFStandard.PDFX42008; o.preserveEditing = false; o.layers = false;
d.saveAs(f, o, true);
if (!f.exists || f.length < 1000) throw new Error('ps_press.pdf was not written');

var pc = d.duplicate('pgd_proof_copy', true); app.activeDocument = pc;
pc.convertProfile('U.S. Web Coated (SWOP) v2', Intent.RELATIVECOLORIMETRIC, true, false);
pc.changeMode(ChangeMode.RGB);
var lay = pc.artLayers[0]; lay.name = 'press proof (stand-in)'; lay.duplicate(d, ElementPlacement.PLACEATBEGINNING);
pc.close(SaveOptions.DONOTSAVECHANGES); app.activeDocument = d;
say('layers: ' + d.layers.length + ' (original kept, proof copy on top); mode ' + d.mode);

var proof = d.layers[0], i, vis = [];
proof.blendMode = BlendMode.DIFFERENCE;
var g = new ActionDescriptor(); g.putBoolean(C2T('Dplc'), true); executeAction(C2T('MrgV'), g, DialogModes.NO);
var diff = d.activeLayer; proof.blendMode = BlendMode.NORMAL;
var t = new ActionDescriptor(); t.putInteger(C2T('Lvl '), 12); executeAction(C2T('Thrs'), t, DialogModes.NO);
for (i = 0; i < d.layers.length; i++) { vis.push(d.layers[i].visible); if (d.layers[i] != diff && d.layers[i].name != diff.name) d.layers[i].visible = false; }
var s = new ActionDescriptor(); s.putReference(C2T('null'), selRef()); var rc = new ActionReference(); rc.putEnumerated(C2T('Chnl'), C2T('Chnl'), C2T('RGB ')); s.putReference(C2T('T   '), rc); executeAction(C2T('setd'), s, DialogModes.NO);
var gw = d.artLayers.add(); gw.name = 'gamut warning (stand-in)'; d.selection.fill(hexc('#7F7F7F')); d.selection.deselect();
diff.remove();
for (i = 0; i < d.layers.length; i++) d.layers[i].visible = true;
say('layers: ' + d.layers.length);

var out = new Folder(OUT); if (!out.exists) out.create();
var f = new File(out.fsName + '/ps_spots.pdf');
var o = new PDFSaveOptions(); o.spotColors = true; o.layers = false; o.preserveEditing = false;
d.saveAs(f, o, true);
if (!f.exists || f.length < 1000) throw new Error('ps_spots.pdf was not written');
